import { BaseRpcContext } from './base-rpc.context.js';
/**
 * @publicApi
 */
export class RedisContext extends BaseRpcContext {
    constructor(args) {
        super(args);
    }
    /**
     * Returns the name of the channel.
     */
    getChannel() {
        return this.args[0];
    }
    /**
     * Returns the metadata the client attached to the packet, if any.
     */
    getMetadata() {
        return this.args[1];
    }
}
